//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry, capped without overflowing.
    pub(crate) fn initial_delay(&self) -> u64 {
        self.base_delay_ms.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn initial_delay_is_bounded() {
        let config = RetryConfig {
            max_attempts: 2,
            base_delay_ms: 50,
            max_delay_ms: 10,
        };
        assert_eq!(config.initial_delay(), 10);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;
    let mut delay_ms = config.initial_delay();

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(delay_ms);
                delay_ms = delay_ms.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut attempts = 0;
        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            attempts += 1;
            if attempts < 5 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(attempts, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut attempts = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            attempts += 1;
            Err(RetryError::Permanent("bad input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(attempts, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut attempts = 0;
        let result = run_job(&config(3, 1, 10), &mut sleeper, || {
            attempts += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(attempts, 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }

    #[test]
    fn delay_growth_handles_overflow_and_saturates() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(4, u64::MAX, u64::MAX), &mut sleeper, || {
            Err(RetryError::Transient("temporary".into()))
        });

        assert!(result.is_err());
        assert_eq!(sleeper.sleeps, vec![u64::MAX, u64::MAX, u64::MAX]);
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error represents a temporary failure.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn classifies_only_transient_errors_as_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid".into()).is_transient());
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_until_success() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 5,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 | 2 => Err(RetryError::Transient("service unavailable".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![5, 10]);
}
